// TypeScript Version: 4.1

import dlagts = require( './index' );


// TESTS //

// The function returns a number...
{
	const A = new Float64Array( 3 );
	const B = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const D = new Float64Array( 1 );
	const IN = new Int32Array( 3 );
	const Y = new Float64Array( 3 );
	const TOL = new Float64Array( 1 );

	dlagts( 1, 3, A, B, C, D, IN, Y, TOL ); // $ExpectType number
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const A = new Float64Array( 3 );
	const B = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const D = new Float64Array( 1 );
	const IN = new Int32Array( 3 );
	const Y = new Float64Array( 3 );
	const TOL = new Float64Array( 1 );

	dlagts( '1', 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( true, 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( false, 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( null, 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( undefined, 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( [], 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( {}, 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( ( x: number ): number => x, 3, A, B, C, D, IN, Y, TOL ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a number...
{
	const A = new Float64Array( 3 );
	const B = new Float64Array( 2 );
	const C = new Float64Array( 2 );
	const D = new Float64Array( 1 );
	const IN = new Int32Array( 3 );
	const Y = new Float64Array( 3 );
	const TOL = new Float64Array( 1 );

	dlagts( 1, '3', A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, true, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, false, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, null, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, undefined, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, [], A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, {}, A, B, C, D, IN, Y, TOL ); // $ExpectError
	dlagts( 1, ( x: number ): number => x, A, B, C, D, IN, Y, TOL ); // $ExpectError
}

